import { type ReactElement, type ReactNode, useCallback, useState } from "react";
import { type LayoutChangeEvent, StyleSheet, View, type ViewProps } from "react-native";
import Animated, { interpolate, useAnimatedStyle } from "react-native-reanimated";
import { useAccordionItemPart, useAccordionPart } from "./accordion.context";
import { ACCORDION_CONTENT_FADE, ACCORDION_UNMEASURED, accordionVariants } from "./accordion.variants";

export type AccordionContentProps = Omit<ViewProps, "style"> & {
	className?: string;
	children?: ReactNode;
};

/**
 * The panel an item discloses.
 *
 * **Its height is measured and animated, never laid out.** The outer view clips,
 * and its height runs from zero to whatever the inner view reported. The animation
 * therefore lives on this one node: whatever sits below follows it through
 * ordinary layout, with nothing to opt into. The alternative — unmounting the
 * content and letting a whole-tree layout transition reflow the screen — makes
 * every sibling on the page a participant in this component's animation.
 *
 * The inner view is **out of flow**, so its height is its content's and can never
 * be fed back the clip's own animated one. In flow it is laid out against that
 * height, and a panel measured while the clip sits at zero reports its padding and
 * nothing else.
 *
 * **The content mounts on first expand and stays mounted.** Nothing renders until
 * an item is first opened, so a screen of collapsed panels costs an empty view
 * each; once opened, the subtree survives every later collapse with its scroll
 * position, its form state and its media intact. A panel that unmounted would
 * destroy all three on every tap.
 *
 * That is what the three accessibility props are for. Mounted content is content a
 * screen reader will read and a finger can reach, so a collapsed panel has to say
 * it is not there — an unmounting accordion never has to think about this.
 *
 * **It reports its first measurement and never starts the travel itself.** The
 * item owns the spring alone; see `onMeasured` on the item context for the race
 * that rule exists to close.
 */
export function AccordionContent({ className, children, ...props }: AccordionContentProps): ReactElement {
	const { size } = useAccordionPart("Accordion.Content");
	const { contentHeight, isExpanded, onMeasured, progress } = useAccordionItemPart("Accordion.Content");
	const slots = accordionVariants({ size });

	// Adjusted during render rather than in an effect, so the panel mounts in the
	// same commit as the tap that opened it. Waiting a frame would put the first
	// measurement — and therefore the start of the travel — one frame later still.
	const [hasExpanded, setHasExpanded] = useState(isExpanded);
	if (isExpanded && !hasExpanded) setHasExpanded(true);

	// Whether this panel has ever reported a height. Until it has, the clip must
	// not constrain anything — see `accordionStyleSheet.measuring` below.
	const [isMeasured, setMeasured] = useState(false);

	const handleLayout = useCallback(
		(event: LayoutChangeEvent) => {
			const wasMeasured = contentHeight.value > ACCORDION_UNMEASURED;
			contentHeight.value = event.nativeEvent.layout.height;

			// The panel reports its first measurement and stops there — it must not
			// start the travel itself. `onLayout` is dispatched from the native side
			// and can land either side of React's effects, so a spring started here
			// is sometimes cancelled a moment later by the cleanup of the item's
			// effect it raced, leaving the panel shut and the indicator pointing the
			// wrong way. Telling the item instead leaves one owner of the spring.
			if (wasMeasured) return;
			setMeasured(true);
			onMeasured();
		},
		[contentHeight, onMeasured]
	);

	// Height and opacity off the one `progress`, never off a timing of their own —
	// so there is no second clock the panel's position can drift from. The fade
	// closes before the height does, which is what keeps the content legible for
	// most of the travel rather than half transparent at its midpoint.
	const clipStyle = useAnimatedStyle(() => ({
		height: progress.value * Math.max(contentHeight.value, 0),
		opacity: interpolate(
			progress.value,
			[0, ACCORDION_CONTENT_FADE.start, ACCORDION_CONTENT_FADE.end, 1],
			[0, 0, 1, 1]
		),
	}));

	return (
		<Animated.View
			accessibilityElementsHidden={!isExpanded}
			className={slots.content()}
			importantForAccessibility={isExpanded ? "auto" : "no-hide-descendants"}
			// Never `auto` while measuring: the clip is stretched over its own item
			// for that commit, and an invisible layer over a trigger is a tap that
			// goes nowhere.
			pointerEvents={isExpanded && isMeasured ? "auto" : "none"}
			style={isMeasured ? clipStyle : accordionStyleSheet.measuring}
		>
			{hasExpanded ? (
				<View className={slots.contentInner({ className })} onLayout={handleLayout} {...props}>
					{children}
				</View>
			) : null}
		</Animated.View>
	);
}
AccordionContent.displayName = "DelacourUI.Accordion.Content";

const accordionStyleSheet = StyleSheet.create({
	/**
	 * What the clip wears until its panel has reported a height.
	 *
	 * Absolutely positioned over its own item, so it is out of the item's layout and
	 * nothing on screen moves while it measures, and transparent, so nothing shows
	 * either. What matters is what it is *not*: it is not `height: 0`. A clip
	 * already at zero squashes an in-flow child to its padding, and never fires
	 * `onLayout` at all for an out-of-flow one — its frame is empty, so no layout
	 * event is emitted and the measurement arrives only when something unrelated
	 * forces a relayout, minutes later or never. Both were found on a simulator.
	 *
	 * The switch to the animated clip happens on the commit the measurement lands,
	 * while `progress` is still zero — so the panel goes from taking no space to
	 * taking none, and the travel starts from there.
	 */
	measuring: { bottom: 0, left: 0, opacity: 0, position: "absolute", right: 0, top: 0 },
});

import type { ReactElement } from "react";
import { Text } from "@registry/ui/text";
import { useAccordionPart } from "./accordion.context";
import type { AccordionTextProps } from "./accordion.types";
import { accordionVariants } from "./accordion.variants";

/**
 * The trigger's secondary line, a step down in scale and on the muted token.
 *
 * Sits under the title inside the trigger's own text column, which the trigger
 * assembles — so the two stack without a wrapper part between them.
 */
export function AccordionDescription({ className, ...props }: AccordionTextProps): ReactElement {
	const { size } = useAccordionPart("Accordion.Description");
	return <Text className={accordionVariants({ size }).description({ className })} {...props} />;
}
AccordionDescription.displayName = "DelacourUI.Accordion.Description";

import { type ReactElement, type ReactNode, useMemo } from "react";
import type { ViewProps } from "react-native";
import Animated, { interpolate, useAnimatedStyle } from "react-native-reanimated";
import { IconChevronBottom } from "@registry/icons/central";
import { Icon, type IconDefaults, IconDefaultsProvider } from "@registry/ui/icon";
import { useAccordionItemPart, useAccordionPart } from "./accordion.context";
import { ACCORDION_INDICATOR_ROTATION, ACCORDION_INDICATOR_TOKEN, accordionVariants } from "./accordion.variants";

/** What a render-function indicator is handed. */
export type AccordionIndicatorState = { isExpanded: boolean };

export type AccordionIndicatorProps = Omit<ViewProps, "children" | "style"> & {
	/**
	 * Turn with the panel. Set `false` for a glyph that *swaps* rather than
	 * rotates — a plus becoming a minus reads as broken when it also spins.
	 */
	isAnimated?: boolean;
	className?: string;
	/**
	 * A glyph, or a function handed the item's settled state.
	 *
	 * The function form exists so a swapping glyph needs no component of its own:
	 * reading `isExpanded` means calling a hook, and a hook cannot be called in the
	 * parent's JSX. `Slider.Track` takes a function for the same reason.
	 *
	 * It matters more than convenience here. A trigger finds its indicator by
	 * element type, so an indicator wrapped in a component of the caller's own is
	 * invisible to it and a second, default one is composed in beside it. Handing
	 * the state over removes the reason to write that wrapper at all.
	 */
	children?: ReactNode | ((state: AccordionIndicatorState) => ReactNode);
};

/**
 * The glyph saying an item opens, turning as it does.
 *
 * Composed into a trigger that holds none, so a bare `<Accordion.Trigger>` is
 * already complete — `Radio`'s rule for its indicator, and the same reasoning: an
 * item has exactly one, so a caller who wrote none wants the default.
 *
 * **The rotation interpolates off the item's own `progress`**, the very value the
 * panel's height reads, so the glyph and the panel are in phase by construction
 * rather than by two springs tuned to match. It also means a custom glyph turns
 * exactly like the default one — pass anything as children and it rotates, unless
 * `isAnimated={false}` says otherwise.
 *
 * The rotation lives on this node rather than on the trigger's because
 * `Pressable`'s own root `Animated.View` already owns `transform` through a
 * `useAnimatedStyle` of its own, and two animated styles on one node fight for
 * the same prop.
 *
 * Its subtree inherits the accordion's glyph step and the muted token, so a
 * composed `<Icon>` needs nothing said at the call site.
 *
 * @example
 * <Accordion.Indicator isAnimated={false}>
 *   {({ isExpanded }) => <Icon icon={isExpanded ? IconMinusSmall : IconPlusSmall} />}
 * </Accordion.Indicator>
 */
export function AccordionIndicator({
	isAnimated = true,
	className,
	children,
	...props
}: AccordionIndicatorProps): ReactElement {
	const { size } = useAccordionPart("Accordion.Indicator");
	const { isExpanded, progress } = useAccordionItemPart("Accordion.Indicator");

	const slots = accordionVariants({ size });
	const glyphClassName = slots.glyph();

	const rotationStyle = useAnimatedStyle(() => ({
		transform: [
			{
				rotate: `${interpolate(
					progress.value,
					[0, 1],
					[ACCORDION_INDICATOR_ROTATION.collapsed, ACCORDION_INDICATOR_ROTATION.expanded]
				)}deg`,
			},
		],
	}));

	const iconDefaults = useMemo<IconDefaults>(
		() => ({ className: glyphClassName, color: ACCORDION_INDICATOR_TOKEN }),
		[glyphClassName]
	);

	return (
		<Animated.View className={slots.indicator({ className })} style={isAnimated ? rotationStyle : undefined} {...props}>
			<IconDefaultsProvider value={iconDefaults}>{renderGlyph(children, isExpanded)}</IconDefaultsProvider>
		</Animated.View>
	);
}
AccordionIndicator.displayName = "DelacourUI.Accordion.Indicator";

/** The caller's glyph, the state they asked for, or the default chevron. */
function renderGlyph(
	children: ReactNode | ((state: AccordionIndicatorState) => ReactNode),
	isExpanded: boolean
): ReactNode {
	if (typeof children === "function") return children({ isExpanded });
	return children ?? <Icon icon={IconChevronBottom} />;
}

import { type ReactElement, type ReactNode, useCallback, useEffect, useMemo, useState } from "react";
import { View, type ViewProps } from "react-native";
import { cancelAnimation, useSharedValue, withSpring } from "react-native-reanimated";
import { type AccordionItemContextValue, AccordionItemProvider, useAccordionPart } from "./accordion.context";
import {
	ACCORDION_SPRING,
	ACCORDION_UNMEASURED,
	accordionVariants,
	isItemExpanded,
	resolveAccordionItemAxes,
} from "./accordion.variants";

export type AccordionItemProps = Omit<ViewProps, "children"> & {
	/** What this item is called in the accordion's value. Must be unique within one. */
	value: string;
	/** Blocks the trigger and fades the row. Inherited from the enclosing accordion. */
	isDisabled?: boolean;
	className?: string;
	children?: ReactNode;
};

/**
 * One section of an accordion: a trigger, and the panel it discloses.
 *
 * Owns the two shared values every animated style on this item reads —
 * `progress` and the panel's measured height — and the one spring that drives
 * them. One source for the height, the fade and the indicator's rotation, so the
 * three cannot drift out of step by a frame.
 *
 * `progress` is seeded from the settled state rather than from zero, so an item
 * mounted open does not animate itself open on its first paint — `Switch`'s rule.
 *
 * An item is expected to hold an `Accordion.Content`. One without a panel has
 * nothing to measure and therefore nothing to travel against, so its indicator
 * stays put — which is the right outcome for a row that discloses nothing.
 */
export function AccordionItem({ value, isDisabled, className, children, ...props }: AccordionItemProps): ReactElement {
	const { expanded, isDisabled: accordionDisabled, size } = useAccordionPart("Accordion.Item");
	const axes = resolveAccordionItemAxes({ own: { isDisabled }, root: { isDisabled: accordionDisabled } });
	const isExpanded = isItemExpanded(expanded, value);

	const progress = useSharedValue(isExpanded ? 1 : 0);
	const contentHeight = useSharedValue(ACCORDION_UNMEASURED);

	// Bumped the first time this item's panel reports a height, purely to make the
	// effect below run again. See `onMeasured` on the item context for why the
	// panel must not start the spring itself.
	const [measurements, setMeasurements] = useState(0);
	const onMeasured = useCallback(() => setMeasurements((count) => count + 1), []);

	// `measurements` is not read in the body — being unread is the whole point of
	// it, the way `settledDrags` is for a `Switch`. The first expand of a panel
	// that has never been mounted has no height to travel against, so this run
	// bails; the measurement that follows is what brings it back.
	// biome-ignore lint/correctness/useExhaustiveDependencies: the extra dependency is the re-run trigger, see above
	useEffect(() => {
		if (isExpanded && contentHeight.value === ACCORDION_UNMEASURED) return;

		progress.value = withSpring(isExpanded ? 1 : 0, ACCORDION_SPRING);

		// Without this an item unmounted mid-travel leaves its spring running.
		return () => cancelAnimation(progress);
	}, [contentHeight, isExpanded, measurements, progress]);

	const context = useMemo<AccordionItemContextValue>(
		() => ({ contentHeight, isDisabled: axes.isDisabled, isExpanded, onMeasured, progress, value }),
		[axes.isDisabled, contentHeight, isExpanded, onMeasured, progress, value]
	);

	return (
		<AccordionItemProvider value={context}>
			<View className={accordionVariants({ isDisabled: axes.isDisabled, size }).item({ className })} {...props}>
				{children}
			</View>
		</AccordionItemProvider>
	);
}
AccordionItem.displayName = "DelacourUI.Accordion.Item";

import type { ReactElement } from "react";
import { Text } from "@registry/ui/text";
import { useAccordionPart } from "./accordion.context";
import type { AccordionTextProps } from "./accordion.types";
import { accordionVariants } from "./accordion.variants";

/**
 * The trigger's primary line — what the item is called.
 *
 * Carries its own colour and type scale, read from the accordion's context: a
 * React Native `View` does not cascade colour to a `Text` descendant, so the
 * trigger cannot set it on their behalf.
 */
export function AccordionTitle({ className, ...props }: AccordionTextProps): ReactElement {
	const { size } = useAccordionPart("Accordion.Title");
	return <Text className={accordionVariants({ size }).title({ className })} {...props} />;
}
AccordionTitle.displayName = "DelacourUI.Accordion.Title";

import { Children, isValidElement, type ReactElement, type ReactNode, useCallback, useMemo } from "react";
import { View } from "react-native";
import { type IconDefaults, IconDefaultsProvider } from "@registry/ui/icon";
import { Pressable, type PressableProps } from "@registry/ui/pressable";
import { useAccordionItemPart, useAccordionPart } from "./accordion.context";
import { ACCORDION_FOREGROUND_TOKEN, accordionVariants } from "./accordion.variants";
import { AccordionDescription } from "./accordion-description";
import { AccordionIndicator } from "./accordion-indicator";
import { AccordionTitle } from "./accordion-title";

export type AccordionTriggerProps = Omit<PressableProps, "children" | "disabled" | "onPress"> & {
	className?: string;
	children?: ReactNode;
};

/**
 * The row that opens and closes an item.
 *
 * A `Pressable`, so `feedback`, `haptic`, `pressedScale` and the rest come from
 * there rather than being restated here. Two defaults differ: `fade`, because a
 * full-bleed row that scales reads as the whole card flexing rather than as one
 * row responding — `ListGroup.Item`'s reason — and `haptic="selection"`, because
 * an item is a state toggle and the panel landing is the confirmation, which is
 * `Checkbox`'s and `Switch`'s. `haptic={false}` silences it.
 *
 * `onPress` is the one prop `Omit`ed rather than forwarded: the press **is** the
 * toggle, and a side effect belongs on the accordion's `onValueChange`. The trade
 * `Checkbox` already makes.
 *
 * It assembles its own row — titles and descriptions stack in a column, an
 * indicator is moved to the end, and one is composed in when the children hold
 * none — so the anatomy needs no wrapper part between a trigger and its text.
 *
 * `accessibilityState.expanded` is the only thing added to what `Pressable`
 * already announces. There is deliberately no separate heading element wrapping
 * it: state set in two places is state a screen reader reads out twice.
 */
export function AccordionTrigger({
	feedback = "fade",
	haptic = "selection",
	className,
	children,
	...props
}: AccordionTriggerProps): ReactElement {
	const { size, toggle } = useAccordionPart("Accordion.Trigger");
	const { isDisabled, isExpanded, value } = useAccordionItemPart("Accordion.Trigger");

	const slots = accordionVariants({ size });
	const columnClassName = slots.triggerContent();
	const glyphClassName = slots.glyph();

	const handlePress = useCallback(() => toggle(value), [toggle, value]);

	const content = useMemo(() => composeRow(children, columnClassName), [children, columnClassName]);

	const iconDefaults = useMemo<IconDefaults>(
		() => ({ className: glyphClassName, color: ACCORDION_FOREGROUND_TOKEN }),
		[glyphClassName]
	);

	return (
		<Pressable
			accessibilityState={{ expanded: isExpanded }}
			className={slots.trigger({ className })}
			disabled={isDisabled}
			feedback={feedback}
			haptic={haptic}
			onPress={handlePress}
			{...props}
		>
			<IconDefaultsProvider value={iconDefaults}>{content}</IconDefaultsProvider>
		</Pressable>
	);
}
AccordionTrigger.displayName = "DelacourUI.Accordion.Trigger";

/**
 * Arranges a trigger's children into the row the anatomy describes.
 *
 * Three things happen, and each has a call site it saves:
 *
 * - **Bare strings become a title.** React Native crashes on a raw string outside
 *   a `<Text>`, so `<Accordion.Trigger>Shipping</Accordion.Trigger>` would red-box.
 *   Consecutive strings collapse into one, because `Item {index}` is a single
 *   piece of text and wrapping the parts separately would stack them.
 * - **Titles and descriptions stack in a column.** They are the only children that
 *   belong on top of each other; anything else — a leading `Icon`, a `Badge` — is
 *   left where it was written, as a sibling on the row. That is what makes a
 *   `Accordion.TriggerContent` part unnecessary rather than merely absent.
 * - **The indicator goes last, and is composed in when there is none.** So a
 *   trigger reads as its content and still ends with the glyph that says it opens.
 *
 * Lives here rather than with the root: it is the trigger that arranges its own
 * children, and importing it from `./accordion` would close a cycle. See AGENTS.md.
 */
function composeRow(children: ReactNode, columnClassName: string): ReactNode {
	const items = Children.toArray(children);
	const row: ReactNode[] = [];
	const trailing: ReactNode[] = [];
	let column: ReactNode[] = [];
	let run: (string | number)[] = [];
	let hasIndicator = false;

	const flushRun = () => {
		if (run.length === 0) return;
		column.push(<AccordionTitle key={`title-${column.length}`}>{run.join("")}</AccordionTitle>);
		run = [];
	};

	const flushColumn = () => {
		if (column.length === 0) return;
		row.push(
			<View className={columnClassName} key={`content-${row.length}`}>
				{column}
			</View>
		);
		column = [];
	};

	for (const child of items) {
		if (typeof child === "string" || typeof child === "number") {
			run.push(child);
			continue;
		}
		flushRun();

		if (isValidElement(child) && child.type === AccordionIndicator) {
			hasIndicator = true;
			trailing.push(child);
			continue;
		}

		if (isValidElement(child) && (child.type === AccordionTitle || child.type === AccordionDescription)) {
			column.push(child);
			continue;
		}

		flushColumn();
		row.push(child);
	}

	flushRun();
	flushColumn();

	if (!hasIndicator) trailing.push(<AccordionIndicator key="indicator" />);

	return [...row, ...trailing];
}

import { createContext, type ReactElement, type ReactNode, use } from "react";
import type { SharedValue } from "react-native-reanimated";
import type { AccordionSize, AccordionVariant } from "./accordion.variants";

export type AccordionContextValue = {
	variant: AccordionVariant;
	size: AccordionSize;
	/** Every item is inert. An item's own `isDisabled` still overrides it, either way. */
	isDisabled: boolean;
	/** Which items are open, on the **JS thread**. */
	expanded: readonly string[];
	/** Opens or closes one item. Stable for the accordion's lifetime. */
	toggle: (value: string) => void;
};

export type AccordionItemContextValue = {
	/** What this item is called in the accordion's expanded set. */
	value: string;
	isDisabled: boolean;
	/** Whether this item is open, on the **JS thread** — what accessibility reads. */
	isExpanded: boolean;
	/**
	 * How far open this item is, on the **UI thread**: `0` closed, `1` open.
	 *
	 * The one value every animated style on this item reads — the panel's height,
	 * the panel's opacity and the indicator's rotation. One source rather than
	 * three, so they cannot drift out of step by a frame.
	 *
	 * It agrees with {@link AccordionItemContextValue.isExpanded} at rest and
	 * disagrees for the whole of a spring, which is what keeps the animation off
	 * the JS thread entirely.
	 */
	progress: SharedValue<number>;
	/**
	 * The panel's natural height in points, from its own `onLayout`.
	 *
	 * Holds {@link ACCORDION_UNMEASURED} until a panel has reported, which is not
	 * the same as a panel that measured zero: the item's spring waits on the first
	 * measurement rather than travelling against a height that is not there yet.
	 */
	contentHeight: SharedValue<number>;
	/**
	 * Told by the panel that it has measured itself for the first time.
	 *
	 * Internal machinery, and the reason the item is the **only** owner of the
	 * spring. The panel cannot start the travel itself: `onLayout` is dispatched
	 * from the native side and can land either side of React's effects, so a panel
	 * that started its own spring would sometimes have it cancelled a moment later
	 * by the cleanup of the effect it raced. This hands the item a reason to re-run
	 * instead — `Slider`'s and `Switch`'s `settledDrags`, for the same reason: a
	 * counter whose only job is to give an effect something to fire on.
	 */
	onMeasured: () => void;
};

const AccordionContext = createContext<AccordionContextValue | null>(null);
const AccordionItemContext = createContext<AccordionItemContextValue | null>(null);

/**
 * Supplies one accordion's axes and its selection to every item beneath it.
 *
 * Lives in its own module, importing nothing but React and types, so a part can
 * read it without importing `./accordion`. That import would close a cycle, and
 * Metro serves a partially initialised module for a cycle — leaving the context
 * `undefined` at import time and red-boxing the app on a cold start.
 */
export function AccordionProvider({
	value,
	children,
}: {
	value: AccordionContextValue;
	children: ReactNode;
}): ReactElement {
	return <AccordionContext value={value}>{children}</AccordionContext>;
}
AccordionProvider.displayName = "DelacourUI.Accordion.Provider";

/** Supplies one item's own state and shared values to its trigger, indicator and panel. */
export function AccordionItemProvider({
	value,
	children,
}: {
	value: AccordionItemContextValue;
	children: ReactNode;
}): ReactElement {
	return <AccordionItemContext value={value}>{children}</AccordionItemContext>;
}
AccordionItemProvider.displayName = "DelacourUI.Accordion.ItemProvider";

/** The enclosing accordion's state, or null outside an `<Accordion>`. */
export function useAccordionContext(): AccordionContextValue | null {
	return use(AccordionContext);
}

/**
 * Reads the enclosing accordion's axes and selection.
 *
 * Lets a custom child style itself to match, or drive the selection, without the
 * accordion having to pass props down through every item. Throws outside an
 * `<Accordion>` — use {@link useAccordionContext} where the enclosing accordion is
 * optional.
 */
export function useAccordion(): AccordionContextValue {
	const context = useAccordionContext();
	if (!context) {
		throw new Error("useAccordion must be called inside an <Accordion>.");
	}
	return context;
}

/** The enclosing item's state, or null outside an `<Accordion.Item>`. */
export function useAccordionItemContext(): AccordionItemContextValue | null {
	return use(AccordionItemContext);
}

/**
 * Reads the enclosing item's state.
 *
 * This is what a custom indicator reaches for: `isExpanded` to swap a glyph, or
 * `progress` to animate against exactly the travel the panel is running. Throws
 * outside an `<Accordion.Item>`.
 */
export function useAccordionItem(): AccordionItemContextValue {
	const context = useAccordionItemContext();
	if (!context) {
		throw new Error("useAccordionItem must be called inside an <Accordion.Item>.");
	}
	return context;
}

/**
 * The enclosing accordion's state, for a compound part that cannot work without one.
 *
 * Internal: deliberately not re-exported from `index.ts`. A caller outside the
 * library wants {@link useAccordion}, whose error message names the hook rather
 * than a part.
 */
export function useAccordionPart(component: string): AccordionContextValue {
	const context = useAccordionContext();
	if (!context) {
		throw new Error(`${component} must be rendered inside an <Accordion>.`);
	}
	return context;
}

/** The enclosing item's state, for a compound part that cannot work without one. */
export function useAccordionItemPart(component: string): AccordionItemContextValue {
	const context = useAccordionItemContext();
	if (!context) {
		throw new Error(`${component} must be rendered inside an <Accordion.Item>.`);
	}
	return context;
}

import { Children, isValidElement, type ReactElement, type ReactNode, useCallback, useMemo, useRef } from "react";
import { View, type ViewProps } from "react-native";
import { useControllableState } from "@registry/hooks/use-controllable-state";
import { Separator } from "@registry/ui/separator";
import { type AccordionContextValue, AccordionProvider } from "./accordion.context";
import {
	ACCORDION_DEFAULT_SIZE,
	ACCORDION_DEFAULT_VARIANT,
	type AccordionSelection,
	type AccordionSelectionMode,
	type AccordionSize,
	type AccordionVariant,
	accordionVariants,
	toExpandedList,
	toggleExpandedValue,
} from "./accordion.variants";
import { AccordionContent } from "./accordion-content";
import { AccordionDescription } from "./accordion-description";
import { AccordionIndicator } from "./accordion-indicator";
import { AccordionItem } from "./accordion-item";
import { AccordionTitle } from "./accordion-title";
import { AccordionTrigger } from "./accordion-trigger";

export type AccordionBaseProps = Omit<ViewProps, "children"> & {
	variant?: AccordionVariant;
	size?: AccordionSize;
	/** Draw a divider between adjacent items. On by default. */
	isDivided?: boolean;
	/** Blocks every trigger and fades every row. An item's own prop still overrides it. */
	isDisabled?: boolean;
	/**
	 * Whether the last open item may be closed. On by default.
	 *
	 * It bounds the *set*, never a single item: in `multiple` mode an item still
	 * closes while another is open, and only the last one is refused.
	 */
	isCollapsible?: boolean;
	className?: string;
	children?: ReactNode;
};

export type AccordionProps = AccordionBaseProps & AccordionSelection;

type AccordionBodyProps = AccordionBaseProps & {
	selectionMode?: AccordionSelectionMode;
	expanded?: readonly string[];
	defaultExpanded: readonly string[];
	onExpandedChange?: (expanded: readonly string[]) => void;
};

/**
 * Everything the accordion does, over one internal list of open values.
 *
 * Split from the root so the root can be nothing but a narrow on `selectionMode`.
 * `useControllableState` cannot be called conditionally, so the two shapes a
 * caller can hold — a string or an array — are converted to this one list at the
 * boundary and back again on the way out. Two hooks would be two pieces of state
 * for one answer.
 */
function AccordionBody({
	selectionMode = "single",
	variant = ACCORDION_DEFAULT_VARIANT,
	size = ACCORDION_DEFAULT_SIZE,
	isDivided = true,
	isDisabled = false,
	isCollapsible = true,
	expanded: expandedProp,
	defaultExpanded,
	onExpandedChange,
	className,
	children,
	...props
}: AccordionBodyProps): ReactElement {
	// A ref-backed trampoline, so the accordion's own context does not change
	// identity whenever the caller passes a fresh arrow — which would re-render
	// every item on every render of the screen above it. `Switch` registers its
	// toggle with a `Field` the same way, for the same reason.
	const changeRef = useRef(onExpandedChange);
	changeRef.current = onExpandedChange;
	const handleChange = useCallback((next: readonly string[]) => changeRef.current?.(next), []);

	const [expanded, setExpanded] = useControllableState<readonly string[]>({
		defaultValue: defaultExpanded,
		onChange: handleChange,
		value: expandedProp,
	});

	// Read by `toggle` rather than closed over, so one stable callback serves the
	// accordion for its whole life. A `toggle` that changed on every expansion
	// would be a new context value on every expansion, and therefore a re-render
	// of every item rather than of the one that moved.
	const expandedRef = useRef(expanded);
	expandedRef.current = expanded;

	const toggle = useCallback(
		(value: string) => {
			const next = toggleExpandedValue({ expanded: expandedRef.current, isCollapsible, selectionMode, value });
			// Refused, by identity. A tap the rules reject must not re-render and
			// must not report an `onValueChange` for a change that did not happen.
			if (next === expandedRef.current) return;
			setExpanded(next);
		},
		[isCollapsible, selectionMode, setExpanded]
	);

	const context = useMemo<AccordionContextValue>(
		() => ({ expanded, isDisabled, size, toggle, variant }),
		[expanded, isDisabled, size, toggle, variant]
	);

	const slots = accordionVariants({ size, variant });
	const dividerClassName = slots.divider();

	const content = useMemo(
		() => (isDivided ? withDividers(children, dividerClassName) : children),
		[children, dividerClassName, isDivided]
	);

	return (
		<AccordionProvider value={context}>
			<View className={slots.root({ className })} {...props}>
				{content}
			</View>
		</AccordionProvider>
	);
}
AccordionBody.displayName = "DelacourUI.Accordion.Body";

/**
 * Inserts a divider between adjacent items.
 *
 * A pair is skipped when either side already is a `Separator`, so a hand-placed
 * divider is never doubled. `Children.toArray` drops the nulls and booleans a
 * conditional child leaves behind, so an item rendered only some of the time does
 * not strand a divider where nothing follows it — which counting indices against
 * the raw children cannot do.
 */
function withDividers(children: ReactNode, dividerClassName: string): ReactNode {
	const items = Children.toArray(children);
	const output: ReactNode[] = [];

	for (const [index, child] of items.entries()) {
		if (index > 0 && !isSeparator(items[index - 1]) && !isSeparator(child)) {
			output.push(<Separator className={dividerClassName} key={`divider-${index}`} />);
		}
		output.push(child);
	}

	return output;
}

function isSeparator(node: ReactNode): boolean {
	return isValidElement(node) && node.type === Separator;
}

function AccordionRoot(props: AccordionProps): ReactElement {
	// The one place the union is narrowed, and it happens before anything is
	// destructured — which is what keeps the two shapes correlated. Destructure
	// first and `onValueChange` widens to a union of two functions that cannot be
	// called, which is what forces a cast or a `@ts-expect-error` on every other
	// implementation of this component.
	if (props.selectionMode === "multiple") {
		const { value, defaultValue, onValueChange, ...rest } = props;
		return (
			<AccordionBody
				{...rest}
				defaultExpanded={toExpandedList(defaultValue)}
				expanded={value === undefined ? undefined : toExpandedList(value)}
				onExpandedChange={(next) => onValueChange?.([...next])}
			/>
		);
	}

	const { value, defaultValue, onValueChange, ...rest } = props;
	return (
		<AccordionBody
			{...rest}
			defaultExpanded={toExpandedList(defaultValue)}
			expanded={value === undefined ? undefined : toExpandedList(value)}
			onExpandedChange={(next) => onValueChange?.(next[0] ?? null)}
		/>
	);
}

/**
 * A set of rows that each disclose a panel.
 *
 * `selectionMode` decides how many open at once: `single` (the default) keeps one
 * open and reports a `string | null`, `multiple` keeps any number and reports a
 * `string[]`. The two are a real discriminated union, so an array `defaultValue`
 * on a single accordion is a compile error rather than a runtime surprise.
 *
 * **A panel's height is measured and animated**, so the animation lives on the
 * panel's own node and whatever sits below simply follows it — no sibling on the
 * screen has to opt into anything. Its
 * height, its fade and the indicator's rotation all run off one shared value per
 * item, so they cannot drift out of step by a frame, and a tap mid-travel reverses
 * the spring rather than restarting it.
 *
 * **A panel mounts on first expand and stays mounted**, so a form inside one keeps
 * what was typed, a list keeps where it was scrolled, and a video keeps playing
 * position across every later collapse.
 *
 * Dividers are inserted between adjacent items rather than written out at every
 * call site, inset to line up with the triggers' own padding. A `Separator` placed
 * by hand is respected — no divider is added on either side of it — so a caller can
 * control one gap without turning the feature off. `isDivided={false}` turns it off.
 *
 * `isCollapsible={false}` keeps one item open at all times. It bounds the set and
 * never a single item, so in `multiple` mode a row still closes while another is
 * open and only the last one is refused.
 *
 * **State works either way from one hook**: pass `value` to control it, or nothing
 * and let it hold its own.
 *
 * @example
 * <Accordion>
 *   <Accordion.Item value="shipping">
 *     <Accordion.Trigger>
 *       <Accordion.Title>Shipping</Accordion.Title>
 *       <Accordion.Description>2–5 business days</Accordion.Description>
 *     </Accordion.Trigger>
 *     <Accordion.Content>
 *       <Text.Paragraph>Tracked, and signed for over $200.</Text.Paragraph>
 *     </Accordion.Content>
 *   </Accordion.Item>
 * </Accordion>
 *
 * @example
 * <Accordion onValueChange={setOpen} selectionMode="multiple" value={open}>
 *   {sections.map((section) => (
 *     <Accordion.Item key={section.id} value={section.id}>
 *       <Accordion.Trigger>{section.title}</Accordion.Trigger>
 *       <Accordion.Content>{section.body}</Accordion.Content>
 *     </Accordion.Item>
 *   ))}
 * </Accordion>
 */
export const Accordion = Object.assign(AccordionRoot, {
	/** One section: a trigger, and the panel it discloses. */
	Item: AccordionItem,
	/** The row that opens the item. A `Pressable`, so it inherits the whole vocabulary. */
	Trigger: AccordionTrigger,
	/** The trigger's primary line. Bare string children become one automatically. */
	Title: AccordionTitle,
	/** The trigger's secondary line, stacked under the title. */
	Description: AccordionDescription,
	/** The glyph that turns as the panel opens. Composed in when a trigger holds none. */
	Indicator: AccordionIndicator,
	/** The measured, clipped panel. Mounts on first expand and stays mounted. */
	Content: AccordionContent,
	displayName: "DelacourUI.Accordion",
});

import type { TextProps } from "react-native";

/**
 * The shape of a trigger's two text lines, `Title` and `Description`.
 *
 * Shared by both parts, and by the root's trigger, which wraps bare string
 * children in a `Accordion.Title` — three modules, so it lives in a leaf rather
 * than in one of them arbitrarily. `ListGroupTextProps` is the same type for the
 * same reason.
 */
export type AccordionTextProps = TextProps & { className?: string };

import type { VariantProps } from "tailwind-variants";
import { tv } from "@registry/lib/tv";
import type { IconSize } from "@registry/ui/icon/icon.variants";

/** How the surface is painted. `ListGroup`'s set — an accordion is the same kind of thing. */
export const ACCORDION_VARIANTS = ["default", "secondary", "tertiary", "transparent"] as const;

export const ACCORDION_SIZES = ["sm", "md", "lg"] as const;

/** Whether one item may be open at a time, or any number of them. */
export const ACCORDION_SELECTION_MODES = ["single", "multiple"] as const;

export type AccordionVariant = (typeof ACCORDION_VARIANTS)[number];
export type AccordionSize = (typeof ACCORDION_SIZES)[number];
export type AccordionSelectionMode = (typeof ACCORDION_SELECTION_MODES)[number];

/**
 * The axes an accordion falls back to when nothing names one.
 *
 * Named once because two places read them — `defaultVariants` below and the root,
 * which settles them before `tv` is ever called. A test pins the pair, since a
 * drift between them is an accordion that renders at one size and reports another.
 */
export const ACCORDION_DEFAULT_VARIANT: AccordionVariant = "default";
export const ACCORDION_DEFAULT_SIZE: AccordionSize = "md";

/**
 * The step every glyph in an accordion is drawn at — the indicator, or an icon a
 * caller composes into a trigger.
 *
 * One step rather than two, so a chevron and a leading glyph on the same row are
 * the same mark. `Switch` makes the same call for the two ends of its track. The
 * `glyph` slot writes the class out, because Tailwind's scanner is static, and a
 * test pins the two together.
 */
export const ACCORDION_GLYPH_STEP: Record<AccordionSize, IconSize> = { sm: "xs", md: "sm", lg: "md" };

/** Theme token an `Icon` composed into a trigger inherits. */
export const ACCORDION_FOREGROUND_TOKEN = "foreground";

/**
 * Theme token the indicator inherits.
 *
 * Quieter than the title it sits beside, and a test pins that the two differ.
 * The chevron is chrome telling you the row opens; the title is the content. Paint
 * both `foreground` and the glyph carries the same weight as the words.
 */
export const ACCORDION_INDICATOR_TOKEN = "muted-foreground";

/**
 * The one spring an accordion runs.
 *
 * **The panel's height, the panel's opacity and the indicator's rotation all read
 * it**, off a single `progress` shared value, so they cannot drift out of step by
 * a frame. Two springs is the failure this constant exists to prevent: a stiffer
 * layout than chevron leaves the glyph visibly lagging the panel on every tap.
 *
 * **Critically damped**, which is `Switch`'s rule turned inside out. A switch damps
 * its thumb because an overshoot squashes against a capsule that clips it; a panel
 * damps its height because an overshoot draws the panel *taller* than its content
 * measured, flashing the surface behind it for a frame at the end of every expand.
 * A test pins the damping ratio at or above one, and below the point where it crawls.
 */
export const ACCORDION_SPRING = { damping: 26, mass: 0.4, stiffness: 400 } as const;

/**
 * Where the indicator points at each end of the travel, in degrees.
 *
 * A half turn, so a chevron pointing down at rest points up when the panel is
 * open. Interpolated off the same `progress` as the height rather than driven by
 * an effect of its own, so the two are in phase by construction.
 */
export const ACCORDION_INDICATOR_ROTATION = { collapsed: 0, expanded: 180 } as const;

/**
 * What {@link AccordionItemContextValue.contentHeight} holds before a panel has
 * ever reported its own layout.
 *
 * Negative rather than zero, because the two mean different things and the
 * difference is load-bearing. A panel that measured `0` is a real answer — a
 * panel whose content rendered nothing — and an item that treated it as "still
 * waiting" would never start its spring, leaving the indicator stuck pointing the
 * wrong way for an empty panel. Only a value no layout can produce can mean
 * *unmeasured*.
 *
 * The height style therefore floors it: `progress * max(contentHeight, 0)`.
 */
export const ACCORDION_UNMEASURED = -1;

/**
 * The window of the travel the panel's opacity ramps across.
 *
 * Tied to `progress` like everything else, but ahead of it: a panel whose opacity
 * tracked its height linearly would be half transparent at the midpoint of every
 * expand, which reads as content struggling to arrive rather than as a panel
 * opening. Closing the fade at {@link ACCORDION_CONTENT_FADE.end} leaves the last
 * of the travel to the height alone.
 */
export const ACCORDION_CONTENT_FADE = { start: 0.1, end: 0.6 } as const;

/**
 * Styling for every part of an accordion.
 *
 * One slotted `tv()` rather than a call per part, because the parts cannot import
 * the root without closing a cycle (AGENTS.md rule 3) yet all of them read the
 * same `size`.
 *
 * **Size is not decoration.** It drives the trigger's metrics, the title and
 * description type scale, the indicator's glyph step, the panel's padding *and*
 * the divider inset. Those six belong on one axis rather than in six places that
 * can drift apart — the divider inset tracking the trigger's own padding is
 * asserted as a pair for exactly that reason, and so is the panel's.
 *
 * **The variant paints the root and nothing else.** Only the root has a surface;
 * a trigger or a panel that also changed with it would be a second source for one
 * colour. A test pins that.
 *
 * **`overflow-hidden` on the root is load-bearing, not tidiness.** A panel
 * expanding inside it would otherwise square off the group's own rounded corners
 * — `ListGroup`'s rule, and the same one that makes a pressed trigger fade to the
 * edge of its own box.
 *
 * **`overflow-hidden` on `content` is the disclosure itself.** That slot's height
 * is an animated style running from zero to the height its contents measured, so
 * without the clip a collapsed panel would draw its content straight over the row
 * below it.
 *
 * **`contentInner` is out of flow, and the panel measures itself before the clip
 * is allowed to constrain anything.** Both halves were found the hard way on a
 * simulator. In normal flow the child is laid out against the clip's own height,
 * so a panel measured while the clip sits at `height: 0` reports its padding and
 * nothing else — sixteen points for a paragraph. Out of flow it measures its
 * content honestly, but a view that *mounts* absolutely into a parent already at
 * `height: 0` never fires `onLayout` at all: the frame is empty, no layout event
 * is emitted, and the panel waits for a measurement that arrives only when
 * something unrelated forces a relayout — minutes later, or never.
 *
 * So the clip has two phases, and `accordion-content.tsx` owns the switch: while
 * the panel has never measured it is positioned absolutely over its own item, which
 * takes it out of the item's layout entirely and keeps it invisible; once it has a
 * height it becomes the animated clip. Nothing moves on screen between the two,
 * because the travel has not started yet.
 *
 * **The disabled fade lands on `item`, never on `trigger`.** The trigger is a
 * `Pressable`, whose root `Animated.View` writes `opacity` every frame through a
 * `useAnimatedStyle` of its own — a class on that node is overwritten silently,
 * which is the failure `Switch` and `Radio` both record.
 *
 * No slot worn by a `View` carries `text-*`; a React Native `View` does not
 * cascade colour to a `Text` descendant, so the treatment lives on the `title` and
 * `description` slots. See AGENTS.md rule 1.
 *
 * Free of React Native imports so it stays unit-testable — `bun test` cannot parse
 * React Native's Flow-typed source. See AGENTS.md.
 */
export const accordionVariants = tv({
	slots: {
		/** The clipped, rounded surface every item sits in. */
		root: "overflow-hidden border border-transparent",
		/** Positioning only for a divider the root inserts — the line is a `Separator`. */
		divider: "",
		/** One item's column: its trigger, then its panel. Wears the disabled fade. */
		item: "",
		/** The row that opens the item. A `Pressable`, so it carries no opacity of its own. */
		trigger: "w-full flex-row items-center",
		/** The trigger's text column, taking whatever width the indicator leaves. */
		triggerContent: "min-w-0 flex-1 justify-center gap-0.5",
		/** The box the indicator turns inside. Its rotation is an animated style. */
		indicator: "items-center justify-center",
		/** Edge length any glyph in an accordion inherits. */
		glyph: "",
		/** The trigger's primary line. Carries its own colour — a `View` cannot cascade one. */
		title: "font-medium text-foreground",
		/** The trigger's secondary line, a step down in scale and on the muted token. */
		description: "text-muted-foreground",
		/** The clip. Its height is an animated style, never a class. */
		content: "w-full overflow-hidden",
		/** The measured layer, out of flow so no clip height can squash what it reports. */
		contentInner: "absolute top-0 right-0 left-0",
	},
	variants: {
		variant: {
			default: { root: "border-border bg-card" },
			secondary: { root: "bg-secondary" },
			tertiary: { root: "bg-tertiary" },
			transparent: { root: "bg-transparent" },
		},
		size: {
			sm: {
				root: "rounded-xl",
				trigger: "min-h-12 gap-2.5 px-3 py-3",
				divider: "mx-3",
				contentInner: "px-3 pb-3",
				glyph: "size-icon-xs",
				title: "text-sm",
				description: "text-xs",
			},
			md: {
				root: "rounded-2xl",
				trigger: "min-h-14 gap-3 px-4 py-3.5",
				divider: "mx-4",
				contentInner: "px-4 pb-4",
				glyph: "size-icon-sm",
				title: "text-base",
				description: "text-sm",
			},
			lg: {
				root: "rounded-2xl",
				trigger: "min-h-16 gap-3.5 px-5 py-4",
				divider: "mx-5",
				contentInner: "px-5 pb-5",
				glyph: "size-icon-md",
				title: "text-lg",
				description: "text-base",
			},
		},
		// The empty `false` branch is load-bearing typing, not a placeholder. `tv`
		// derives the prop type from the declared keys, so a map with only `true`
		// types the prop as `true` rather than `boolean`.
		isDisabled: { true: { item: "opacity-50" }, false: {} },
	},
	defaultVariants: {
		variant: ACCORDION_DEFAULT_VARIANT,
		size: ACCORDION_DEFAULT_SIZE,
		isDisabled: false,
	},
});

export type AccordionVariantProps = VariantProps<typeof accordionVariants>;

/** An accordion where one item is open at a time, or none. */
export type AccordionSingleSelection = {
	selectionMode?: "single";
	/** Controlled. `null` is a controlled *empty*, not an absence. */
	value?: string | null;
	/** Which item starts open while uncontrolled. */
	defaultValue?: string | null;
	onValueChange?: (value: string | null) => void;
};

/** An accordion where any number of items are open at once. */
export type AccordionMultipleSelection = {
	selectionMode: "multiple";
	/** Controlled. */
	value?: string[];
	/** Which items start open while uncontrolled. */
	defaultValue?: string[];
	onValueChange?: (value: string[]) => void;
};

/**
 * The two shapes an accordion's state can take.
 *
 * A **true** discriminated union, so `selectionMode="single"` with an array
 * `defaultValue` is a type error rather than something the toggle has to defend
 * against at runtime. Intersecting a union like this with a widened
 * `defaultValue?: string | string[]` defeats it entirely — every member re-admits
 * both shapes, and the callback ends up typed as a function *returning* a union
 * rather than a union of functions.
 *
 * Lives here rather than in `accordion.types.ts` because that file imports React
 * Native's `ViewProps`, and the root's selection maths has to stay reachable from
 * `bun test`.
 */
export type AccordionSelection = AccordionSingleSelection | AccordionMultipleSelection;

/** Whether one item's value is in the expanded set. */
export function isItemExpanded(expanded: readonly string[], value: string): boolean {
	return expanded.includes(value);
}

/**
 * Normalises every shape a caller can hold into the one list the root keeps.
 *
 * The root holds a single `string[]` whichever mode is in play, because
 * `useControllableState` cannot be called conditionally and two hooks would be two
 * pieces of state for one answer. The caller's shape is converted at the boundary
 * instead — here on the way in, and by a narrow on `selectionMode` on the way out.
 *
 * It copies rather than aliasing, so a caller's array cannot be handed to React as
 * state it still holds a reference to.
 */
export function toExpandedList(value: string | readonly string[] | null | undefined): string[] {
	if (value === null || value === undefined) return [];
	return typeof value === "string" ? [value] : [...value];
}

/**
 * The whole state transition a tap on a trigger makes.
 *
 * Pure, so `bun test` reaches the entire matrix — the trade `toggleCheckedValue`
 * already makes for `Checkbox.Group`.
 *
 * **A real change is always a new array**, because React bails out of a re-render
 * on an unchanged reference and a mutation would flip the state while leaving the
 * screen alone. **A refused tap returns its own input**, by identity, so the root
 * can skip it — a rejected tap must not re-render and must not report an
 * `onValueChange` for a change that did not happen.
 *
 * **`isCollapsible` bounds the set, never a single item.** In multiple mode that
 * distinction is the whole point: an item still closes while others stay open, and
 * only the last one is refused. Reading it as "no item may ever close" makes a
 * multiple accordion add-only, which is a control that fills up and never empties.
 */
export function toggleExpandedValue({
	expanded,
	value,
	selectionMode,
	isCollapsible,
}: {
	expanded: readonly string[];
	value: string;
	selectionMode: AccordionSelectionMode;
	isCollapsible: boolean;
}): readonly string[] {
	const isExpanded = isItemExpanded(expanded, value);

	if (selectionMode === "single") {
		if (!isExpanded) return [value];
		return isCollapsible ? [] : expanded;
	}

	if (!isExpanded) return [...expanded, value];
	if (!isCollapsible && expanded.length === 1) return expanded;
	return expanded.filter((entry) => entry !== value);
}

/** What one item was given at its own call site. */
export type AccordionItemOwnAxes = { isDisabled?: boolean };

/** What the enclosing accordion publishes. */
export type AccordionRootAxes = { isDisabled?: boolean };

/** Every axis an item settles, ready to hand to {@link accordionVariants}. */
export type AccordionItemAxes = { isDisabled: boolean };

/**
 * Settles one item's axes from the two places they can come from.
 *
 * A two-rung ladder — the item's own prop first, the accordion last — so
 * `<Accordion isDisabled>` dims every row with nothing said at a call site, while
 * `isDisabled={false}` still opts one item back in. `??` throughout and never
 * `||`, so an explicit `false` is a value rather than an absence.
 *
 * The accordion reaches this one *state* axis only; it cannot acquire a paint axis
 * by accident, and a test pins that.
 *
 * Pure, so the whole matrix is reachable from `bun test`. See AGENTS.md.
 */
export function resolveAccordionItemAxes({
	own,
	root,
}: {
	own?: AccordionItemOwnAxes;
	root?: AccordionRootAxes | null;
}): AccordionItemAxes {
	return { isDisabled: own?.isDisabled ?? root?.isDisabled ?? false };
}
